/* tool 123: Ergo auction settlement builder — the highest bid
   wins (first-listed on a tie); sold settles in one transaction
   with the seller receiving the winning bid minus the disclosed
   1% fee (of the WINNING BID, rounded up, minimum 0.001 ERG) and
   every losing bid refunded bid minus one miner fee; a missed
   reserve charges no fee and refunds every bid the same way.
   Every expected value below was computed independently in
   Python before the JS existed (oracle-auction.py, exact
   integer arithmetic). */
const AUCTION_PAY_D = app.p2pkAddressFromPublicKey("02c6047f9441ed7d6d3045406e95c07cd85c778e4b8cef3ca7abac09b95c709ee5", "mainnet");
