/* tool 124: Ergo escrow settlement builder — one deposit, two
   parties, three outcomes. Release: seller gets the deposit
   minus the disclosed 1% fee (of the deposit), miner fee on
   top. Refund: NO fee, buyer gets the deposit minus one miner
   fee. Split: seller share = floor(deposit * bps / 10000),
   buyer share is the rest, fee is 1% of the SELLER'S SHARE
   ONLY. Every figure below was computed with an independent
   Python oracle before the JS existed (oracle-escrow.py,
   exact integer arithmetic); MAIN, SPLIT3333 and BIG were
   also matched against hand arithmetic. */
check("escrow tool on hub", html.includes('id="escrow-calc"') && html.includes("Ergo escrow settlement builder") && html.includes("not an escrow contract") && readme.includes("Ergo escrow settlement builder"));
check("escrow oracle MAIN: a released 200 ERG deposit pays the seller minus the 1% fee", (() => { const r = app.buildEscrowPlan(PAY_A, PAY_C, "GPU rig sale", "200", "release", "", "0.0011"); return r.valid === true && r.network === "Mainnet" && r.outcome === "release" && r.depositNano === "200000000000" && r.serviceFeeNano === "2000000000" && r.serviceFeeWasMinimum === false && r.sellerNetNano === "198000000000" && r.buyerNetNano === "0" && r.sellerShareNano === "200000000000" && r.buyerShareNano === "0" && r.splitBps === null && r.minerFeeNano === "1100000" && r.totalNano === "200001100000" && r.totalErg === "200.0011" && r.anyBelowSafeMin === false && r.includesServiceAddress === false && (BigInt(r.sellerNetNano) + BigInt(r.serviceFeeNano)).toString() === r.depositNano; })());
check("escrow oracle REFUND: a refund charges no fee and returns the deposit minus one miner fee", (() => { const r = app.buildEscrowPlan(PAY_A, PAY_C, "GPU rig sale", "200", "refund", "", "0.0011"); return r.valid === true && r.outcome === "refund" && r.serviceFeeNano === "0" && r.sellerNetNano === "0" && r.buyerNetNano === "199998900000" && r.buyerShareNano === "200000000000" && r.totalNano === "200000000000" && (BigInt(r.buyerNetNano) + BigInt(r.minerFeeNano)).toString() === r.depositNano; })());
check("escrow oracle SPLIT50: a 50/50 split of 200 ERG, fee on the seller's share only", (() => { const r = app.buildEscrowPlan(PAY_A, PAY_C, "GPU rig sale", "200", "split", "50", "0.0011"); return r.valid === true && r.outcome === "split" && r.splitBps === "5000" && r.splitPercent === "50" && r.sellerShareNano === "100000000000" && r.buyerShareNano === "100000000000" && r.serviceFeeNano === "1000000000" && r.sellerNetNano === "99000000000" && r.buyerNetNano === "100000000000" && r.totalNano === "200001100000" && (BigInt(r.sellerNetNano) + BigInt(r.serviceFeeNano) + BigInt(r.buyerNetNano)).toString() === r.depositNano; })());
