check("escrow oracle MINFEE: a released 0.05 ERG deposit hits the minimum fee", (() => { const r = app.buildEscrowPlan(PAY_A, PAY_C, "Tiny deal", "0.05", "release", "", "0.001"); return r.valid === true && r.serviceFeeNano === "1000000" && r.serviceFeeWasMinimum === true && r.sellerNetNano === "49000000" && r.totalNano === "51000000"; })());
