  push(app.writeVlqBig(1n)); for (let i = 0; i < 32; i++) bytes.push(0xaa); push(app.writeVlqBig(0n)); push(app.writeVlqBig(0n));
  push(app.writeVlqBig(BigInt(diIds.length))); diIds.forEach((id) => push(id));
  push(app.writeVlqBig(BigInt(tkIds.length))); tkIds.forEach((id) => push(id));
  push(app.writeVlqBig(1n));
