/* mutation fuzz guard: byte-level hostile inputs through the serialized-data parsers.
   The probes (hidden_files/probe-mutation-fuzz*.js) drove ~79,000 mutated,
   random and hostile inputs through these parsers with zero throws, hangs
   or unstructured verdicts; this pinned subset (deterministic seed) keeps
   the never-throw/structured-verdict property from regressing. */
check("mutated byte inputs never throw the serialized-data parsers", (() => {
  let s = 0xF00DBEAD;
  const rnd = () => { s |= 0; s = (s + 0x6D2B79F5) | 0; let t = Math.imul(s ^ (s >>> 15), 1 | s); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const ri = (n) => Math.floor(rnd() * n);
  const toHex = (a) => a.map((b) => b.toString(16).padStart(2, "0")).join("");
  const HEX64 = /^[0-9a-f]{64}$/;
  const mutate = (hex) => {
    const a = []; for (let i = 0; i < hex.length; i += 2) a.push(parseInt(hex.slice(i, i + 2), 16));
    const kind = ri(5);
    if (kind === 0) { const n = 1 + ri(3); for (let i = 0; i < n; i++) a[ri(a.length)] = ri(256); }
    else if (kind === 1) a.length = 1 + ri(a.length);
    else if (kind === 2) { const n = 1 + ri(12); for (let i = 0; i < n; i++) a.push(ri(256)); }
    else if (kind === 3) { const p = ri(a.length), len = 1 + ri(Math.min(16, a.length - p)); for (let i = p; i < p + len; i++) a[i] = 0; }
    else { const p = ri(a.length), len = 1 + ri(Math.min(16, a.length - p)); for (let i = p; i < p + len; i++) a[i] = 0xff; }
    return toHex(a);
  };
  const targets = [
    [BOX1, (h) => app.parseErgoBox(h), ["boxId"]],
    [TX_V2, (h) => app.parseErgoTransaction(h), ["txId"]],
    [SEG_TREE, (h) => app.analyzeErgoTree(h), []],
    [HDR_V4, (h) => app.inspectBlockHeader(h, ""), ["headerId"]],
  ];
  let calls = 0, seenInvalid = 0;
  for (let r = 0; r < 60; r++) {
    for (const [v, fn, ids] of targets) {
      calls++;
      const m = mutate(v);
      let out;
      try { out = fn(m); } catch { return false; }
      if (!out || typeof out !== "object" || typeof out.valid !== "boolean") return false;
      if (!out.valid) seenInvalid++;
      for (const f of ids) if (out.valid && out[f] != null && !HEX64.test(out[f])) return false;
    }
  }
  return calls === 240 && seenInvalid > 0;
})());

check("line endings: a lone CR is a line break everywhere a paste is split into lines, and CRLF never counts as two", (() => { const cr = (s) => s.replace(/\n/g, "\r"); const pay = app.buildPayrollPlan(PAY_LIST3, "0.0011"); const payCr = app.buildPayrollPlan(cr(PAY_LIST3), "0.0011"); if (!(pay.valid && payCr.valid && payCr.totalNano === pay.totalNano)) return false; const dupCr = app.buildPayrollPlan("Alice, " + PAY_A + ", 1\ralice, " + PAY_B + ", 1", "0.001"); if (dupCr.valid !== false || !/line 2 repeats line 1/.test(dupCr.reason)) return false; const bs = app.summarizeBoxSet(BOX1 + "\n" + BOX2); const bsCr = app.summarizeBoxSet(BOX1 + "\r" + BOX2); if (!(bs.valid && bsCr.valid && bsCr.totalNano === bs.totalNano)) return false; const outText = "value: 2000000\ntree: 0008cd038d39af8c37583609ff51c6a577efe60684119da2fbd0d75f9c72372886a58a63\nheight: 900000\ntoken: " + "aa".repeat(32) + " 7\nregister: long:430550309"; const twoLf = app.parseTxBuildOutputs(outText + "\n\n" + outText); const twoCr = app.parseTxBuildOutputs(cr(outText + "\n\n" + outText)); const twoCrlf = app.parseTxBuildOutputs((outText + "\n\n" + outText).replace(/\n/g, "\r\n")); return twoLf.valid && twoLf.outputs.length === 2 && twoCr.valid && twoCr.outputs.length === 2 && twoCrlf.valid && twoCrlf.outputs.length === 2; })());

check("line endings: U+2028 and U+2029 are line breaks everywhere a paste is split into lines, and two outputs joined only by them never merge into one", (() => { const pay = app.buildPayrollPlan(PAY_LIST3, "0.0011"); const payLs = app.buildPayrollPlan(PAY_LIST3.replace(/\n/g, "\u2028"), "0.0011"); const payPs = app.buildPayrollPlan(PAY_LIST3.replace(/\n/g, "\u2029"), "0.0011"); if (!(pay.valid && payLs.valid && payPs.valid && payLs.totalNano === pay.totalNano && payPs.totalNano === pay.totalNano)) return false; const dupLs = app.buildPayrollPlan("Alice, " + PAY_A + ", 1\u2028alice, " + PAY_B + ", 1", "0.001"); if (dupLs.valid !== false || !/line 2 repeats line 1/.test(dupLs.reason)) return false; const bs = app.summarizeBoxSet(BOX1 + "\n" + BOX2); const bsLs = app.summarizeBoxSet(BOX1 + "\u2028" + BOX2); const bsPs = app.summarizeBoxSet(BOX1 + "\u2029" + BOX2); if (!(bs.valid && bsLs.valid && bsPs.valid && bsLs.totalNano === bs.totalNano && bsPs.totalNano === bs.totalNano)) return false; const outText = "value: 2000000\ntree: 0008cd038d39af8c37583609ff51c6a577efe60684119da2fbd0d75f9c72372886a58a63\nheight: 900000\ntoken: " + "aa".repeat(32) + " 7\nregister: long:430550309"; const twoLs = app.parseTxBuildOutputs((outText + "\n\n" + outText).replace(/\n/g, "\u2028")); const twoPs = app.parseTxBuildOutputs((outText + "\n\n" + outText).replace(/\n/g, "\u2029")); return twoLs.valid && twoLs.outputs.length === 2 && twoPs.valid && twoPs.outputs.length === 2; })());

check("line endings: VT (U+000B), FF (U+000C) and NEL (U+0085) are line breaks everywhere a paste is split into lines, completing the Unicode mandatory-break set, and two outputs joined only by them never merge into one", (() => { const pay = app.buildPayrollPlan(PAY_LIST3, "0.0011"); const outText = "value: 2000000\ntree: 0008cd038d39af8c37583609ff51c6a577efe60684119da2fbd0d75f9c72372886a58a63\nheight: 900000\ntoken: " + "aa".repeat(32) + " 7\nregister: long:430550309"; for (const sep of ["\u000b", "\u000c", "\u0085"]) { const p = app.buildPayrollPlan(PAY_LIST3.replace(/\n/g, sep), "0.0011"); if (!(pay.valid && p.valid && p.totalNano === pay.totalNano)) return false; const dup = app.buildPayrollPlan("Alice, " + PAY_A + ", 1" + sep + "alice, " + PAY_B + ", 1", "0.001"); if (dup.valid !== false || !/line 2 repeats line 1/.test(dup.reason)) return false; const bs = app.summarizeBoxSet(BOX1 + "\n" + BOX2); const bsSep = app.summarizeBoxSet(BOX1 + sep + BOX2); if (!(bs.valid && bsSep.valid && bsSep.totalNano === bs.totalNano)) return false; const two = app.parseTxBuildOutputs((outText + "\n\n" + outText).replace(/\n/g, sep)); if (!(two.valid && two.outputs.length === 2)) return false; } return true; })());

